// Generated by vibelang from e2e/messages.ts; the migrate flow writes it again with each batch.
/** Transcript bubbles only: Timeline repeats message text, including in hidden descendants. */
export const messageIn = (conversation, text) => conversation.locator(".sui-chat-messages .sui-chat-message", { hasText: text });
/** The person's bubble, never an answer that quotes their question. */
export const questionIn = (conversation, text) => messageIn(conversation, text).and(conversation.locator('[data-role="user"]'));
/** The first answer to the first matching question, preserving chronological pairing. */
export const answerTo = (conversation, question) => questionIn(conversation, question).first().locator('xpath=following-sibling::*[@data-role="assistant"][1]');
